static screen_mode_t g_screen_mode = SCREEN_IDLE;
static lv_obj_t *g_dev_code_lbl  = NULL;   /* 主页设备码标签 */
static lv_obj_t *g_dev_code_title = NULL;  /* 主页"设备码"标题 */
