/****************************************************************************
 * 设备码：首次启动生成 UUID，持久化到 /data/device_code
 ****************************************************************************/

static void generate_device_code(void)
{
  /* 尝试读取已有的设备码 */
  FILE *fp = fopen(DEVICE_CODE_FILE, "r");
  if (fp)
    {
      if (fgets(g_device_code, sizeof(g_device_code), fp))
        {
          /* 去掉换行 */
          char *nl = strchr(g_device_code, '\n');
          if (nl) *nl = '\0';
          if (strlen(g_device_code) == 36)
            {
              fclose(fp);
              printf("Device code loaded: %s\n", g_device_code);
              return;
            }
        }
      fclose(fp);
    }

  /* 没有有效设备码，生成新的 UUID */
  fp = fopen("/dev/urandom", "r");
  if (!fp)
    {
      /* fallback: 用时间戳 */
      srand(time(NULL));
      snprintf(g_device_code, sizeof(g_device_code),
               "%08x-%04x-%04x-%04x-%08x%04x",
               (unsigned)time(NULL), rand() & 0xffff, rand() & 0xffff,
               rand() & 0xffff, rand(), rand() & 0xffff);
    }
  else
    {
      unsigned char rb[16];
      fread(rb, 1, 16, fp);
      fclose(fp);

      /* RFC 4122 variant 1 */
      rb[6] = (rb[6] & 0x0f) | 0x40;  /* version 4 */
      rb[8] = (rb[8] & 0x3f) | 0x80;  /* variant 1 */

      snprintf(g_device_code, sizeof(g_device_code),
               "%02x%02x%02x%02x-%02x%02x-%02x%02x-%02x%02x-%02x%02x%02x%02x%02x%02x",
               rb[0], rb[1], rb[2], rb[3], rb[4], rb[5], rb[6], rb[7],
               rb[8], rb[9], rb[10], rb[11], rb[12], rb[13], rb[14], rb[15]);
    }

  /* 保存到文件 */
  fp = fopen(DEVICE_CODE_FILE, "w");
  if (fp)
    {
      fprintf(fp, "%s\n", g_device_code);
      fclose(fp);
    }

  printf("Device code generated: %s\n", g_device_code);
}

/****************************************************************************
 * HTTP 轮询：curl GET /api/device/<code>/screen → 解析 JSON
 ****************************************************************************/

static void fetch_screen_cb(lv_timer_t *timer)
{
  LV_UNUSED(timer);

  /* 只在主页且 WiFi 已连接时轮询 */
  if (g_page != PAGE_HOME || g_wifi_ssid[0] == '\0')
    return;

  char url[256];
  snprintf(url, sizeof(url),
           "curl -s -m 5 http://%s:%d/api/device/%s/screen 2>/dev/null",
           SERVER_HOST, SERVER_PORT, g_device_code);

  FILE *fp = popen(url, "r");
  if (!fp)
    return;

  char resp[512] = "";
  size_t n = fread(resp, 1, sizeof(resp) - 1, fp);
  pclose(fp);
  resp[n] = '\0';

  printf("Screen API response: %s\n", resp);

  /* 简单 JSON 解析：找 "type" 字段 */
  char *type_ptr = strstr(resp, "\"type\"");
  if (!type_ptr)
    return;

  /* 跳到冒号后面的值 */
  type_ptr = strchr(type_ptr, ':');
  if (!type_ptr) return;
  type_ptr++;

  /* 跳过空格和引号 */
  while (*type_ptr == ' ' || *type_ptr == '"') type_ptr++;

  if (strncmp(type_ptr, "idle", 4) == 0)
    {
      g_screen_mode = SCREEN_IDLE;
      if (g_status_lbl)
        lv_label_set_text(g_status_lbl, "等待绑定...");
      printf("Screen mode: idle\n");
    }
  else if (strncmp(type_ptr, "wallpaper", 9) == 0)
    {
      g_screen_mode = SCREEN_WALLPAPER;
      if (g_status_lbl)
        lv_label_set_text(g_status_lbl, "壁纸模式");
      printf("Screen mode: wallpaper\n");
      /* TODO: 下载并显示壁纸图片 */
    }
  else if (strncmp(type_ptr, "news", 4) == 0)
    {
      g_screen_mode = SCREEN_NEWS;
      if (g_status_lbl)
        lv_label_set_text(g_status_lbl, "资讯模式");
      printf("Screen mode: news\n");
      /* TODO: 下载并显示资讯截图 */
    }
}

/****************************************************************************
