  char cmd[256];
  snprintf(cmd, sizeof(cmd),
           "curl -s -m 3 -X POST http://%s:%d/api/device/%s/heartbeat > /dev/null 2>&1",
           SERVER_HOST, SERVER_PORT, g_device_code);
  system(cmd);
}

