static char      g_wifi_ssid[64]   = "";

/* 设备码 & 云端状态 */
static char g_device_code[37] = "";
static screen_mode_t g_screen_mode = SCREEN_IDLE;
static lv_obj_t *g_dev_code_lbl  = NULL;
static lv_obj_t *g_dev_code_title = NULL;
static lv_obj_t *g_status_lbl    = NULL;

    /* 800ms 后模拟连接成功 */
    lv_timer_create(wifi_connect_done_cb, 800, (void *)ssid);
}

/****************************************************************************
 * Device code: generate UUID for simulator
 ****************************************************************************/

static void generate_device_code(void)
{
    /* Generate a random UUID for the simulator */
    srand((unsigned)time(NULL) ^ (unsigned)getpid());
    snprintf(g_device_code, sizeof(g_device_code),
             "%08x-%04x-%04x-%04x-%08x%04x",
             (unsigned)time(NULL), rand() & 0xffff, rand() & 0xffff,
             rand() & 0xffff, rand(), rand() & 0xffff);
    printf("Simulator device code: %s\n", g_device_code);
}

/****************************************************************************
 * HTTP polling: curl GET /api/device/<code>/screen
 ****************************************************************************/

static void fetch_screen_cb(lv_timer_t *timer)
{
    LV_UNUSED(timer);

    /* Only poll on home page when WiFi is "connected" */
    if (g_page != PAGE_HOME || g_wifi_ssid[0] == '\0')
        return;

    char url[256];
    snprintf(url, sizeof(url),
             "curl -s -m 5 http://%s:%d/api/device/%s/screen",
             SERVER_HOST, SERVER_PORT, g_device_code);

    FILE *fp = popen(url, "r");
    if (!fp)
        return;

    char resp[512] = "";
    size_t n = fread(resp, 1, sizeof(resp) - 1, fp);
    pclose(fp);
    resp[n] = '\0';

    printf("Screen API response: %s\n", resp);

    char *type_ptr = strstr(resp, "\"type\"");
    if (!type_ptr)
        return;
    type_ptr = strchr(type_ptr, ':');
    if (!type_ptr) return;
    type_ptr++;
    while (*type_ptr == ' ' || *type_ptr == '"') type_ptr++;

    if (strncmp(type_ptr, "idle", 4) == 0)
    {
        g_screen_mode = SCREEN_IDLE;
        if (g_status_lbl)
            lv_label_set_text(g_status_lbl, "等待绑定...");
    }
    else if (strncmp(type_ptr, "wallpaper", 9) == 0)
    {
        g_screen_mode = SCREEN_WALLPAPER;
        if (g_status_lbl)
            lv_label_set_text(g_status_lbl, "壁纸模式");
    }
    else if (strncmp(type_ptr, "news", 4) == 0)
    {
        g_screen_mode = SCREEN_NEWS;
        if (g_status_lbl)
            lv_label_set_text(g_status_lbl, "资讯模式");
    }
}

/****************************************************************************
 * Heartbeat: POST /api/device/<code>/heartbeat
 ****************************************************************************/

static void heartbeat_cb(lv_timer_t *timer)
{
    LV_UNUSED(timer);
    if (g_wifi_ssid[0] == '\0')
        return;

    char cmd[256];
    snprintf(cmd, sizeof(cmd),
             "curl -s -m 3 -X POST http://%s:%d/api/device/%s/heartbeat > nul 2>&1",
             SERVER_HOST, SERVER_PORT, g_device_code);
    system(cmd);
}

