static void fetch_screen_cb(lv_timer_t *timer)
{
  LV_UNUSED(timer);

  /* 只在主页且 WiFi 已连接时轮询 */
  if (g_page != PAGE_HOME || g_wifi_ssid[0] == '\0')
    return;

  char cmd[256];
  snprintf(cmd, sizeof(cmd),
           "curl -s -m 5 http://%s:%d/api/device/%s/screen > /tmp/screen_resp.json 2>/dev/null",
           SERVER_HOST, SERVER_PORT, g_device_code);
  system(cmd);

  FILE *fp = fopen("/tmp/screen_resp.json", "r");
  if (!fp)
    return;

  char resp[512] = "";
  size_t n = fread(resp, 1, sizeof(resp) - 1, fp);
  fclose(fp);
  resp[n] = '\0';

  printf("Screen API response: %s\n", resp);

  /* 简单 JSON 解析：找 "type" 字段 */
  char *type_ptr = strstr(resp, "\"type\"");
  if (!type_ptr)
    return;

  /* 跳到冒号后面的值 */
  type_ptr = strchr(type_ptr, ':');
  if (!type_ptr) return;
  type_ptr++;

  /* 跳过空格和引号 */
  while (*type_ptr == ' ' || *type_ptr == '"') type_ptr++;

  if (strncmp(type_ptr, "idle", 4) == 0)
    {
      g_screen_mode = SCREEN_IDLE;
      if (g_status_lbl)
        lv_label_set_text(g_status_lbl, "等待绑定...");
      printf("Screen mode: idle\n");
    }
  else if (strncmp(type_ptr, "wallpaper", 9) == 0)
    {
      g_screen_mode = SCREEN_WALLPAPER;
      if (g_status_lbl)
        lv_label_set_text(g_status_lbl, "壁纸模式");
      printf("Screen mode: wallpaper\n");
      /* TODO: 下载并显示壁纸图片 */
    }
  else if (strncmp(type_ptr, "news", 4) == 0)
    {
      g_screen_mode = SCREEN_NEWS;
      if (g_status_lbl)
        lv_label_set_text(g_status_lbl, "资讯模式");
      printf("Screen mode: news\n");
      /* TODO: 下载并显示资讯截图 */
    }
}

