input.newString:
static void generate_device_code(void)
{
  /* 尝试读取已有的设备码 */
  FILE *fp = fopen(DEVICE_CODE_FILE, "r");
  if (fp)
    {
      if (fgets(g_device_code, sizeof(g_device_code), fp))
        {
          /* 去掉换行 */
          char *nl = strchr(g_device_code, '\n');
          if (nl) *nl = '\0';
          if (strlen(g_device_code) >= 6)
            {
              fclose(fp);
              printf("Device code loaded: %s\n", g_device_code);
              return;
            }
        }
      fclose(fp);
    }

  /* 没有有效设备码，生成 8 位短码 */
  fp = fopen("/dev/urandom", "r");
  if (!fp)
    {
      srand(time(NULL));
      snprintf(g_device_code, sizeof(g_device_code), "%08x",
               (unsigned)time(NULL) ^ (rand() << 16 | rand()));
    }
  else
    {
      unsigned char rb[4];
      fread(rb, 1, 4, fp);
      fclose(fp);
      snprintf(g_device_code, sizeof(g_device_code), "%02x%02x%02x%02x",
               rb[0], rb[1], rb[2], rb[3]);
    }

  /* 保存到文件 */
  fp = fopen(DEVICE_CODE_FILE, "w");
  if (fp)
    {
      fprintf(fp, "%s\n", g_device_code);
      fclose(fp);
    }

  printf("Device code generated: %s\n", g_device_code);
}

