    }
  else
    {
      unsigned char rb[16];
      fread(rb, 1, 16, fp);
      fclose(fp);

      /* RFC 4122 variant 1 */
      rb[6] = (rb[6] & 0x0f) | 0x40;  /* version 4 */
      rb[8] = (rb[8] & 0x3f) | 0x80;  /* variant 1 */

      snprintf(g_device_code, sizeof(g_device_code),
               "%02x%02x%02x%02x-%02x%02x-%02x%02x-%02x%02x-%02x%02x%02x%02x%02x%02x",
