#define DEVICE_CODE_FILE "/data/device_code"

/* NTP 服务器 */
#define NTP_SERVER    "ntp.aliyun.com"
#define NTP_CMD       "ntpdate " NTP_SERVER " > /dev/null 2>&1"

/* 当前显示模式 */

static void heartbeat_cb(lv_timer_t *timer)
{
  LV_UNUSED(timer);
  if (g_wifi_ssid[0] == '\0')
    return;

  char cmd[256];
  snprintf(cmd, sizeof(cmd),
           "curl -s -m 3 -X POST http://%s:%d/api/device/%s/heartbeat > /dev/null 2>&1",
           SERVER_HOST, SERVER_PORT, g_device_code);
  system(cmd);
}

/****************************************************************************
 * NTP 时间同步：WiFi 连上后自动校时
 ****************************************************************************/

static int g_ntp_synced = 0;

static void ntp_sync_cb(lv_timer_t *timer)
{
  LV_UNUSED(timer);

  /* 只在 WiFi 已连接且未同步时执行 */
  if (g_wifi_ssid[0] == '\0' || g_ntp_synced)
    return;

  printf("NTP syncing from %s ...\n", NTP_SERVER);
  int rc = system(NTP_CMD);
  if (rc == 0)
    {
      g_ntp_synced = 1;
      printf("NTP sync OK\n");
      /* 同步成功后删除定时器 */
      lv_timer_del(timer);
    }
  else
    {
      printf("NTP sync failed, will retry\n");
    }
}

