static void wifi_connect(const char *ssid, const char *pwd)
{
  char buf[96];

  lv_obj_add_flag(g_pwd_sheet, LV_OBJ_FLAG_HIDDEN);
  if (g_wifi_status)
    lv_label_set_text(g_wifi_status, "连接中...");

  snprintf(buf, sizeof(buf), "正在连接 %s ...", ssid);
  wifi_banner_show(buf, 0x475569);

