  lv_label_set_text(g_clock_label, "00:00");

  /* 日期 */
  g_date_label = lv_label_create(info);
  lv_obj_set_style_text_color(g_date_label, color_hex(0x94a3b8), 0);
  set_cn_font(g_date_label);
  lv_label_set_text(g_date_label, "2026年8月23日");

  /* 问候语 */
  lv_obj_t *greet = lv_label_create(info);
  lv_obj_set_style_text_color(greet, color_hex(0xcbd5e1), 0);
  set_cn_font(greet);
  lv_label_set_text(greet, "欢迎使用 OpenVela");
}
